const cfg = $('⚙️ CONFIG').first().json;
const rows = $input.all().map(i => i.json).filter(r => !r.error);

const pending = rows.filter(r => {
  const p = String(r.PROCESADO || '').trim().toUpperCase();
  return p !== 'TRUE' && p !== '1' && p !== 'YES';
});

if (pending.length === 0) return [];

return pending.map(row => ({
  json: {
    TEMA:    String(row.TEMA    || '').trim(),
    ESPECIE: String(row.ESPECIE || 'animal').trim(),
    TIPO:    String(row.TIPO    || 'checklist').trim().toLowerCase(),
    PRECIO:  parseFloat(row.PRECIO) || 19.90,
    SHEET_ID:               cfg.SHEET_ID,
    HOJA_PENDIENTES:        cfg.HOJA_PENDIENTES,
    GOOGLE_DRIVE_FOLDER_ID: cfg.GOOGLE_DRIVE_FOLDER_ID,
    DEEPSEEK_API_KEY:       cfg.DEEPSEEK_API_KEY,
    HOTMART_CLIENT_ID:      cfg.HOTMART_CLIENT_ID,
    HOTMART_CLIENT_SECRET:  cfg.HOTMART_CLIENT_SECRET,
    MONEDA_HOTMART:         cfg.MONEDA_HOTMART,
    WARRANTY_DIAS:          cfg.WARRANTY_DIAS
  }
}));

const p = $input.item.json;
const tipoMap = {
  checklist: 'checklist práctico con ítems accionables (listas de verificación)',
  ebook:     'ebook completo con contenido educativo por capítulos',
  guia:      'guía paso a paso con instrucciones claras',
  tutorial:  'tutorial detallado con pasos y ejercicios prácticos'
};
const tipoLabel = tipoMap[p.TIPO] || 'infoproducto digital';

const sysPrompt = 'Eres experto en creación de infoproductos digitales de alta conversión para el mercado hispanohablante. RESPONDE ÚNICAMENTE CON UN OBJETO JSON VÁLIDO, sin markdown, sin bloques de código, sin texto antes ni después del JSON.';

const userPrompt = `Crea un ${tipoLabel} completo sobre "${p.TEMA}" para dueños de ${p.ESPECIE}s.\n\nREGLAS:\n- Tono cálido, experto y cercano\n- Mínimo 8 secciones\n- Para checklists: 6-10 ítems por sección\n- Para otros: 200-300 palabras por sección\n- descripcion: máx 190 caracteres, sin saltos\n\nJSON ESPERADO:\n{\n  "titulo": "título (máx 80 chars)",\n  "subtitulo": "subtítulo que engancha",\n  "descripcion": "descripción para Hotmart (máx 190 chars)",\n  "palabras_clave": ["kw1","kw2","kw3","kw4","kw5"],\n  "introduccion": "texto intro (2-3 párrafos)",\n  "secciones": [{"titulo": "nombre", "contenido": "texto", "items": ["ítem1"]}],\n  "conclusion": "texto conclusión",\n  "cta": "llamada a la acción"\n}`;

const body = JSON.stringify({
  model: 'deepseek-chat',
  temperature: 0.72,
  max_tokens: 4000,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: sysPrompt },
    { role: 'user',   content: userPrompt }
  ]
});

return { json: { ...p, _dsBody: body } };

const orig = $('📝 Preparar Prompt DeepSeek').item.json;
const resp = $input.item.json;

if (resp.error) {
  return { json: { ...orig, ds: null, _error: resp.error.message || 'Error DeepSeek HTTP' } };
}

const raw = resp.choices?.[0]?.message?.content || resp.choices?.[0]?.text || '';
let ds;
try {
  ds = JSON.parse(raw);
} catch(e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (!m) return { json: { ...orig, ds: null, _error: 'JSON inválido de DeepSeek: ' + raw.substring(0,100) } };
  try { ds = JSON.parse(m[0]); } catch(e2) {
    return { json: { ...orig, ds: null, _error: 'No se pudo parsear respuesta DeepSeek' } };
  }
}

if (!ds || !ds.titulo || !ds.secciones) {
  return { json: { ...orig, ds: null, _error: 'JSON incompleto de DeepSeek (faltan titulo o secciones)' } };
}

return { json: { ...orig, ds } };

const p = $input.item.json;
if (p._error || !p.ds) return { json: { ...p, htmlContent: '' } };

const { ds, TIPO, ESPECIE } = p;
const PC = '#1e40af', AC = '#10b981', yr = new Date().getFullYear();

function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

function buildSection(s, idx) {
  const isCheck = Array.isArray(s.items) && s.items.length > 0;
  let body;
  if (isCheck) {
    const its = s.items.map(it => `<div class="ci"><span class="ck">&#9744;</span><span>${esc(it)}</span></div>`).join('');
    body = `<div class="checklist">${its}</div>`;
  } else {
    body = (s.contenido||'').split(/\n+/).filter(Boolean).map(t=>`<p>${esc(t)}</p>`).join('') || '<p></p>';
  }
  return `<div class="section"><h2>${idx}. ${esc(s.titulo)}</h2>${body}</div>`;
}

const toc = ds.secciones.map((s,i)=>`<li>${i+1}. ${esc(s.titulo)}</li>`).join('');
const secs = ds.secciones.map((s,i)=>buildSection(s,i+1)).join('');
const intro = (ds.introduccion||'').split(/\n+/).filter(Boolean).map(t=>`<p>${esc(t)}</p>`).join('');
const concl = (ds.conclusion||'').split(/\n+/).filter(Boolean).map(t=>`<p>${esc(t)}</p>`).join('');

const css = `*{margin:0;padding:0;box-sizing:border-box}body{font-family:Georgia,'Times New Roman',serif;color:#1a1a2e;background:#fff;font-size:13pt;line-height:1.8}.cover{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;background:linear-gradient(135deg,${PC} 0%,#1e3a8a 100%);color:#fff;padding:80px 60px;text-align:center;page-break-after:always}.cover h1{font-size:2.2em;margin-bottom:24px;line-height:1.2;max-width:700px}.cover h2{font-size:1.2em;font-weight:300;opacity:.88;margin-bottom:48px;max-width:600px}.cover .badge{background:rgba(255,255,255,.15);border:2px solid rgba(255,255,255,.4);border-radius:30px;padding:10px 30px;font-size:.85em;letter-spacing:3px;text-transform:uppercase}.toc{padding:70px 100px;page-break-after:always}.toc h2{font-size:1.7em;color:${PC};border-bottom:3px solid ${PC};padding-bottom:14px;margin-bottom:32px}.toc ol{list-style:none}.toc li{padding:9px 0;border-bottom:1px dotted #d1d5db}.intro,.concl{padding:60px 100px;page-break-after:always}.intro h2,.concl h2{font-size:1.6em;color:${PC};margin-bottom:22px}.intro p,.concl p{margin-bottom:16px}.section{padding:50px 100px;page-break-after:always}.section h2{font-size:1.5em;color:${PC};border-left:5px solid ${AC};padding-left:18px;margin-bottom:28px}.section p{margin-bottom:16px}.checklist{margin-top:8px}.ci{display:flex;align-items:flex-start;gap:14px;padding:12px 16px;margin-bottom:9px;border:1px solid #e5e7eb;border-radius:8px;background:#f9fafb}.ck{font-size:1.2em;color:${PC};flex-shrink:0}.cta-box{margin:40px 100px 60px;padding:50px 60px;background:${PC};color:#fff;border-radius:16px;text-align:center}.cta-box h3{font-size:1.6em;margin-bottom:18px}.cta-box p{font-size:1.1em;opacity:.9}.footer{text-align:center;padding:30px;font-size:.8em;color:#9ca3af;border-top:1px solid #e5e7eb}`;

const html = `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>${esc(ds.titulo)}</title><style>${css}</style></head><body><div class="cover"><h1>${esc(ds.titulo)}</h1><h2>${esc(ds.subtitulo)}</h2><div class="badge">${esc(TIPO.toUpperCase())} &nbsp;|&nbsp; ${esc(ESPECIE.toUpperCase())}</div></div><div class="toc"><h2>&#128203; Contenidos</h2><ol>${toc}</ol></div><div class="intro"><h2>Introducción</h2>${intro}</div>${secs}<div class="concl"><h2>Conclusión</h2>${concl}</div><div class="cta-box"><h3>&#128640; ¡Es Momento de Actuar!</h3><p>${esc(ds.cta)}</p></div><div class="footer">${esc(ds.titulo)} &copy; ${yr} &nbsp;|&nbsp; Todos los derechos reservados<!-- M6_PROCESSED --></div></body></html>`;

return { json: { ...p, htmlContent: html } };

const data = $input.item.json;
if (data._error || !data.htmlContent) {
  return { json: { ...data, _uploadBody: '', _contentType: '' } };
}

const BOUNDARY = 'M6_bnd_' + Date.now();
const meta = { name: '[M6] ' + data.ds.titulo, mimeType: 'application/vnd.google-apps.document' };
if (data.GOOGLE_DRIVE_FOLDER_ID) meta.parents = [data.GOOGLE_DRIVE_FOLDER_ID];

const htmlB64 = Buffer.from(data.htmlContent, 'utf8').toString('base64');
const uploadBody = [
  '--' + BOUNDARY,
  'Content-Type: application/json; charset=UTF-8',
  '',
  JSON.stringify(meta),
  '--' + BOUNDARY,
  'Content-Type: text/html; charset=UTF-8',
  'Content-Transfer-Encoding: base64',
  '',
  htmlB64,
  '--' + BOUNDARY + '--'
].join('\r\n');

return { json: {
  ...data,
  _uploadBody: uploadBody,
  _contentType: 'multipart/related; boundary="' + BOUNDARY + '"'
}};

const orig = $('📦 Preparar Upload a Drive').item.json;
const driveResp = $('☁️ Crear Google Doc (Drive API)').item.json;

const gdocId = (!driveResp.error && driveResp.id) ? driveResp.id : '';
const pdfUrl  = gdocId ? `https://docs.google.com/document/d/${gdocId}/export?format=pdf` : '';
const docLink = gdocId ? `https://docs.google.com/document/d/${gdocId}/view` : '';

let driveError = orig._error || '';
if (!driveError && driveResp.error) driveError = driveResp.error.message || 'Error Drive API';
if (!driveError && !gdocId) driveError = 'Drive no devolvió ID del Doc';

const hotmartBody = (orig.ds && pdfUrl) ? JSON.stringify({
  name: orig.ds.titulo,
  description: orig.ds.descripcion || orig.ds.titulo,
  format: 'EBOOK',
  warranty: orig.WARRANTY_DIAS || 30,
  price: { value: orig.PRECIO, currency_code: orig.MONEDA_HOTMART || 'BRL' },
  resource_url: pdfUrl
}) : '{}';

return { json: {
  ...orig,
  gdocId, pdfUrl, docLink,
  _driveError: driveError,
  _hotmartBody: hotmartBody
}};

const params = $('🗂️ Preparar Payload Hotmart').item.json;
const tokenResp = $input.item.json;
const token = (!tokenResp.error && tokenResp.access_token) ? tokenResp.access_token : '';
const tokenError = tokenResp.error ? (tokenResp.error.message || 'Error token Hotmart') : (token ? '' : 'Token vacío');
return { json: { ...params, _hotmartToken: token, _tokenError: tokenError } };

const params = $('🔀 Merge Token con Params').item.json;
const hotmartResp = $input.item.json;

const driveOK   = !!params.gdocId && !params._driveError;
const tokenOK   = !!params._hotmartToken && !params._tokenError;
const hotmartOK = !hotmartResp.error && !!(hotmartResp.id || hotmartResp.product?.id);

let errorMsg = '';
if (params._error)       errorMsg = params._error;
else if (!driveOK)       errorMsg = params._driveError || 'Error creando Google Doc';
else if (!tokenOK)       errorMsg = params._tokenError || 'Error obteniendo token Hotmart';
else if (!hotmartOK)     errorMsg = hotmartResp.error?.message || JSON.stringify(hotmartResp).substring(0,120);

const success = driveOK && tokenOK && hotmartOK && !params._error;

return { json: {
  _tema:          params.TEMA,
  _titulo:        params.ds?.titulo || params.TEMA,
  _success:       success,
  PROCESADO:      success ? 'TRUE' : 'FALSE',
  PDF_URL:        params.pdfUrl  || '',
  GDOC_ID:        params.gdocId  || '',
  HOTMART_ID:     success ? (String(hotmartResp.id || hotmartResp.product?.id || '')) : '',
  HOTMART_LINK:   success ? (hotmartResp.links?.checkout_url || hotmartResp.checkout_url || 'ver panel Hotmart') : '',
  ERROR:          errorMsg,
  SHEET_ID:       params.SHEET_ID,
  HOJA_PENDIENTES: params.HOJA_PENDIENTES
}};
